from pathlib import Path

p = Path('index.html')
text = p.read_text(encoding='utf-8')

prediction_css = ".predictForm{display:grid;grid-template-columns:1fr 1fr .8fr auto;gap:10px}.predictionHero{display:grid;grid-template-columns:.85fr 1.15fr;gap:12px}.predictionResult{min-height:310px}.moneyBig{font-size:34px;font-weight:950}.rangeGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.rangeBox{border:1px solid var(--line);background:var(--soft);border-radius:8px;padding:10px}.rangeBox b{font-size:20px}.safetyDial{height:180px;border:1px solid var(--line);border-radius:8px;background:conic-gradient(from 180deg,var(--green) calc(var(--score)*1%),var(--soft) 0);display:grid;place-items:center}.safetyDial div{width:124px;height:124px;border:1px solid var(--line);border-radius:8px;background:var(--panel);display:grid;place-items:center;text-align:center}.safetyDial b{font-size:36px}.predictNote{font-size:12px;color:var(--muted);line-height:1.45}"
if '.predictForm{' not in text:
    text = text.replace('.newsMini a:hover{color:var(--green)}@media(max-width:1100px)', '.newsMini a:hover{color:var(--green)}' + prediction_css + '@media(max-width:1100px)', 1)
    text = text.replace('.split,.detailGrid{grid-template-columns:1fr}}@media(max-width:700px)', '.split,.detailGrid,.predictionHero{grid-template-columns:1fr}.predictForm{grid-template-columns:1fr 1fr}}@media(max-width:700px)', 1)
    text = text.replace('.newsGrid,.accountGrid{grid-template-columns:1fr}.scoreBadge', '.newsGrid,.accountGrid,.predictForm,.rangeGrid{grid-template-columns:1fr}.scoreBadge', 1)

text = text.replace('<button class="btn tab" onclick="showPage(\'news\',this)">News</button><button class="btn tab" onclick="showPage(\'backend\',this)">Backend</button>', '<button class="btn tab" onclick="showPage(\'news\',this)">News</button><button class="btn tab" onclick="showPage(\'predict\',this)">Predictions</button><button class="btn tab" onclick="showPage(\'backend\',this)">Backend</button>', 1)

predict_html = '''<section id="predictPage" class="grid page"><section class="panel span12"><div class="section"><h3>Market Predictions</h3><span class="muted">Estimate safety and possible money range from live scanner data</span></div><div class="predictForm"><input id="predictSymbol" class="input" placeholder="Stock, like NVDA" maxlength="12"><input id="predictAmount" class="input" placeholder="Money amount, like 100" inputmode="decimal"><select id="predictHorizon" class="select"><option value="1d">1 day</option><option value="1w" selected>1 week</option><option value="1m">1 month</option></select><button id="predictBtn" class="btn primary">Predict</button></div><p class="predictNote">Research estimate only. It uses current price action, volatility, AI score, news impact, confidence, and invalidation levels. It cannot guarantee profit.</p></section><section class="panel span12"><div class="predictionHero"><div><div class="section"><h3>Safety Score</h3><span class="tag neutral" id="predictSafetyLabel">Waiting</span></div><div id="predictSafetyDial" class="safetyDial" style="--score:50"><div><b id="predictSafetyScore">--</b><small class="muted">safe</small></div></div></div><div id="predictionResult" class="predictionResult detailPanel"><h3>Run a prediction</h3><p class="muted">Type a ticker and how much money you would put in. The site will estimate possible gain, possible loss, and whether the setup looks safer or risky.</p></div></div></section><section class="panel span12"><div class="section"><h3>Top Prediction Ideas</h3><span class="muted">Based on total score, safety, and possible upside</span></div><div id="predictionIdeas" class="cards"></div></section></section>\n'''
if '<section id="predictPage"' not in text:
    text = text.replace('<section id="backendPage"', predict_html + '<section id="backendPage"', 1)

text = text.replace('renderIdeas(all);renderNews();renderBackend()', 'renderIdeas(all);renderNews();renderPredictions(all);renderBackend()', 1)

prediction_js = r'''function money(n){return Number.isFinite(n)?(n<0?'-':'')+'$'+Math.abs(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):'--'}function parseMoney(v){return Number(String(v||'').replace(/[^0-9.]/g,''))||0}function horizonMult(v){return v==='1d'?.55:v==='1m'?1.8:1}function horizonName(v){return v==='1d'?'1 day':v==='1m'?'1 month':'1 week'}function safetyFor(r){const ni=newsImpactFor(r),raw=42+confidence(r)*.22+totalScore(r)*.25+ni.score*.12-riskScore(r)*.28+(signal(r).key==='peak'?-8:signal(r).key==='dip'?4:0);return clamp(Math.round(raw),1,99)}function predictionFor(r,amount,horizon){const p=levels(r),mult=horizonMult(horizon),ni=newsImpactFor(r),safe=safetyFor(r),shares=amount/(r.price||1),baseTarget=Math.max(p.target,r.price+p.vol*1.15),baseStop=Math.min(p.stop,r.price-p.vol*.85),upPct=clamp((baseTarget-r.price)/r.price*100*mult,.4,45),downPct=clamp((r.price-baseStop)/r.price*100*mult,.4,45),expectedPct=clamp((totalScore(r)-50)*.055+(ni.score-50)*.025+(confidence(r)-60)*.025-(riskScore(r)-50)*.035,-downPct,upPct),gain=amount*upPct/100,loss=amount*downPct/100,expected=amount*expectedPct/100;return{r,amount,horizon,shares,safe,upPct,downPct,expectedPct,gain,loss,expected,target:r.price*(1+upPct/100),stop:r.price*(1-downPct/100),label:safe>=75?'Safer':safe>=55?'Moderate':safe>=38?'Risky':'Very risky',ni}}function predictionRead(p){const s=signal(p.r);if(p.safe>=75&&p.expected>0)return`This looks like one of the safer research setups right now. The estimate is positive, but still use the stop range if the chart breaks.`;if(p.expected>0)return`The setup has possible upside, but safety is only ${p.label.toLowerCase()}. Wait for confirmation near the trigger before trusting it.`;if(s.key==='peak')return`The scanner sees peak risk. It may still move, but the safety score says chasing it here is dangerous.`;return`The math does not show a clean edge yet. It may be better to wait for a stronger setup or smaller test amount.`}function predictionHtml(p){const r=p.r,plan=setupPlan(r);return`<div class="line"><div><h3>${clean(r.symbol)} Prediction</h3><div class="muted">${esc(r.name||'')} | ${horizonName(p.horizon)} estimate | ${fmt(r.price)}</div></div><span class="tag ${p.safe>=75?'dip':p.safe<45?'peak':'neutral'}">${p.label}</span></div><div class="moneyBig ${p.expected>=0?'up':'down'}">${money(p.expected)}</div><p class="muted">Estimated expected result on ${money(p.amount)}: <b class="${p.expected>=0?'up':'down'}">${pct(p.expectedPct)}</b>. You would get about <b>${p.shares.toFixed(p.shares>=10?2:4)}</b> shares at the current price.</p><div class="rangeGrid"><div class="rangeBox"><small class="muted">Possible upside</small><b class="up">${money(p.gain)}</b><div class="muted">${pct(p.upPct)} near ${fmt(p.target)}</div></div><div class="rangeBox"><small class="muted">Possible loss</small><b class="down">${money(-p.loss)}</b><div class="muted">-${p.downPct.toFixed(2)}% near ${fmt(p.stop)}</div></div><div class="rangeBox"><small class="muted">News impact</small><b>${p.ni.score}</b><div class="muted">${p.ni.label}</div></div></div><div class="detailGrid"><div class="detailPanel"><h3>What It Means</h3><p class="muted">${predictionRead(p)}</p></div><div class="detailPanel"><h3>Plan</h3><p class="muted">${plan.entry}</p><p class="muted">${plan.exit}</p></div></div>`}function setPredictionSafety(score,label){$('predictSafetyDial').style.setProperty('--score',score);$('predictSafetyScore').textContent=score||'--';$('predictSafetyLabel').textContent=label||'Waiting'}function showPrediction(p){setPredictionSafety(p.safe,p.label);$('predictionResult').innerHTML=predictionHtml(p)}async function runPrediction(){const sym=stockInput($('predictSymbol').value),amount=parseMoney($('predictAmount').value),horizon=$('predictHorizon').value;if(!sym){$('predictionResult').innerHTML='<h3>Type a stock</h3><p class="muted">Use a ticker like AAPL, NVDA, TSLA, or any stock symbol.</p>';setPredictionSafety(0,'Waiting');return}if(!amount){$('predictionResult').innerHTML='<h3>Add money amount</h3><p class="muted">Enter the amount you would invest, like 50 or 100.</p>';setPredictionSafety(0,'Waiting');return}let r=bySym.get(sym);if(!r){$('predictionResult').innerHTML='<h3>Looking up '+esc(sym)+'</h3><p class="muted">Trying a one-off live lookup for this ticker...</p>';try{r=await fetchYahoo(sym);if(r){records.push(r);bySym.set(r.symbol,r)}}catch(e){}}if(!r){$('predictionResult').innerHTML='<h3>Could not find '+esc(sym)+'</h3><p class="muted">Try another stock ticker. Some symbols may not be available from the free data source.</p>';setPredictionSafety(0,'No data');return}showPrediction(predictionFor(r,amount,horizon));renderPredictions([...stockRecords(),...cryptoRecords()])}function quickPredict(sym,amount){$('predictSymbol').value=sym;$('predictAmount').value=amount||parseMoney($('predictAmount').value)||100;showPage('predict');runPrediction()}function renderPredictions(all){if(!$('predictionIdeas'))return;const amount=parseMoney($('predictAmount')?.value)||100,horizon=$('predictHorizon')?.value||'1w';const ranked=all.filter(r=>!isCrypto(r.symbol)).map(r=>predictionFor(r,amount,horizon)).sort((a,b)=>(b.safe+b.expectedPct*2)-(a.safe+a.expectedPct*2));$('predictionIdeas').innerHTML=ranked.slice(0,8).map(p=>`<div class="asset ideaCard" onclick="quickPredict('${p.r.symbol}',${amount})"><div class="ideaHeader"><div><b class="sym">${clean(p.r.symbol)}</b><div class="muted">${esc(p.r.name||'')} | ${fmt(p.r.price)}</div></div><div class="scoreBadge" style="--score:${p.safe}">${p.safe}</div></div><div class="pillRow"><span class="tag ${p.safe>=75?'dip':p.safe<45?'peak':'neutral'}">${p.label}</span><span class="tag gold">Could ${money(p.gain)}</span><span class="tag neutral">Risk ${money(p.loss)}</span></div><div class="bar"><i style="width:${clamp(50+p.expectedPct*3,1,99)}%"></i></div><p class="muted"><b>Estimate:</b> ${money(p.expected)} expected on ${money(amount)} over ${horizonName(horizon)}.</p><p class="muted">${predictionRead(p)}</p></div>`).join('')}
'''
if 'function predictionFor(r,amount,horizon)' not in text:
    text = text.replace('function renderBackend(){', prediction_js + 'function renderBackend(){', 1)

text = text.replace("$('refreshBtn').onclick=load;$('sort').onchange", "$('refreshBtn').onclick=load;$('predictBtn').onclick=runPrediction;$('predictSymbol').onkeydown=e=>{if(e.key==='Enter')runPrediction()};$('predictAmount').onkeydown=e=>{if(e.key==='Enter')runPrediction()};$('predictAmount').oninput=()=>renderPredictions([...stockRecords(),...cryptoRecords()]);$('predictHorizon').onchange=()=>{renderPredictions([...stockRecords(),...cryptoRecords()]);if($('predictSymbol').value&&parseMoney($('predictAmount').value))runPrediction()};$('sort').onchange", 1)
text = text.replace('window.deleteAccount=deleteAccount;setThemeButton()', 'window.deleteAccount=deleteAccount;window.runPrediction=runPrediction;window.quickPredict=quickPredict;setThemeButton()', 1)

required = ['Predictions</button>', '<section id="predictPage"', 'function predictionFor(r,amount,horizon)', "$('predictBtn').onclick=runPrediction", 'window.quickPredict=quickPredict']
missing = [x for x in required if x not in text]
if missing:
    raise SystemExit('Prediction patch failed, missing: ' + ', '.join(missing))

p.write_text(text, encoding='utf-8')
